              "summary": "- 2Q26 매출 $22.97B(+47.7%yoy), EPS $8.38(+32.8%yoy)로 컨센서스 상회- 인크레틴 물량이 가격 하락을 압도, 비만 시장 성장세 확인- 본업 상향분을 M&A로 재투자, 하반기 경구용 GLP-1 처방 추이에 주목",
              "pdfUrl": "https://rreport.einfomax.co.kr/report/eqlxczcxcmmiekkgcgxecie.pdf",
