              "summary": "- 투자 포인트: 1) 사상 최대 수주잔고를 통한 실적 가시성 확보: FY3Q25 수주잔고 1,099억 달러(총 계약가치 1,677억 달러, +18.6% YoY). Marine Systems가 절반 이상을 차지하며 Columbia·Virginia급 핵잠수함 프로그램이 중기 성장의 핵심 축- 안정적 수주 기반은 향후 3~5년 실적 가이던스 상향 여력을 뒷받침할 전망. 2) Aerospace·Marine 주도의 두 자릿수 성장세: FY3Q25 YoY 기준 매출 +10.6%, 영업이익 +12.7%, 희석 EPS +15.8% 기록- 실적 및 밸류에이션: FY3Q25 희석 EPS 3.88달러로 컨센서스(+4.6%) 상회. 12m fwd PER 21.4배로 5년 평균(18.2배) 대비 프리미엄이나, 이는 막대한 수주잔고, 견조한 FCF 마진(7~8%), 낮은 레버리지로 정당화 가능",
